func (l *Limiter) Allow(ctx context.Context, key string) (bool, error) {
	n, err := l.redis.Incr(ctx, windowKey(key)).Result()
	if err != nil {
		// Redis down: let traffic through rather than fail every request.
		l.metrics.FailOpen.Inc()
		return true, nil
	}
	return n <= l.limit, nil
}
